{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.capsule_summary_dashboard AS WITH master AS ( SELECT CAPSULE, SUM(TOTAL_QTY) AS UNITS_SOLD, SUM(GROSS_SALES) AS GMV, SUM(TOTAL_DISCOUNT) AS TOTAL_DISCOUNT, SUM(TOTAL_INWARD_QTY) AS UNITS_RECEIVED, SUM(TOTAL_INVENTORY) AS CURRENT_INVENTORY, SUM(OPENING_GMV) AS OPENING_GMV, SUM(TOTAL_INVENTORY_VALUE) AS INVENTORY_VALUE, SUM(SOLD_MERCHANDISE_VALUE) AS SOLD_MERCHANDISE_VALUE, ROUND( SUM(GROSS_SALES) / NULLIF(SUM(TOTAL_QTY), 0), 2 ) AS ASP, ROUND( SUM(TOTAL_QTY) * 100.0 / NULLIF(SUM(TOTAL_INWARD_QTY), 0), 2 ) AS STR_LIFETIME, ROUND( 100 - ( SUM(TOTAL_QTY) * 100.0 / NULLIF(SUM(TOTAL_INWARD_QTY), 0) ), 2 ) AS STR_REMAINING, ROUND( SUM(TOTAL_INVENTORY) * 100.0 / NULLIF(SUM(TOTAL_INWARD_QTY), 0), 2 ) AS INVENTORY_REMAINING_PCT, ROUND( SUM(TOTAL_DISCOUNT) * 100.0 / NULLIF( SUM(GROSS_SALES) + SUM(TOTAL_DISCOUNT), 0 ), 2 ) AS DISCOUNT_PCT, MAX(DAYS_ACTIVE) AS DAYS_ACTIVE, MAX(STOCK_COVER_DAYS) AS STOCK_COVER_DAYS, MAX(INVENTORY_AGE_BUCKET) AS INVENTORY_AGE_BUCKET, MAX(STR_STATUS) AS STR_STATUS, MAX(FIRST_INWARD_DATE) AS FIRST_INWARD_DATE, MAX(LATEST_INWARD_DATE) AS LATEST_INWARD_DATE, SUM(INWARD_EVENTS) AS INWARD_EVENTS, MAX(REPEAT_ORDER) AS REPEAT_ORDER, MAX(REPEAT_ORDER_FLAG) AS REPEAT_ORDER_FLAG, MAX(ONLINE_NEW_USERS) AS ONLINE_NEW_USERS, MAX(ONLINE_REPEAT_USERS) AS ONLINE_REPEAT_USERS, MAX(ONLINE_LOYAL_USERS) AS ONLINE_LOYAL_USERS, MAX(ONLINE_TOTAL_USERS) AS ONLINE_TOTAL_USERS, MAX(OFFLINE_NEW_USERS) AS OFFLINE_NEW_USERS, MAX(OFFLINE_REPEAT_USERS) AS OFFLINE_REPEAT_USERS, MAX(OFFLINE_TOTAL_USERS) AS OFFLINE_TOTAL_USERS FROM snitch_db.maplemonk.capsule_master_summary_tbl GROUP BY CAPSULE ), customer_metrics AS ( SELECT CAPSULE, COALESCE(ONLINE_NEW_USERS, 0) + COALESCE(OFFLINE_NEW_USERS, 0) AS NEW_USERS, COALESCE(ONLINE_REPEAT_USERS, 0) + COALESCE(OFFLINE_REPEAT_USERS, 0) AS RETURNING_USERS, COALESCE(ONLINE_TOTAL_USERS, 0) + COALESCE(OFFLINE_TOTAL_USERS, 0) AS TOTAL_USERS, COALESCE(ONLINE_LOYAL_USERS, 0) AS LOYAL_USERS, COALESCE(ONLINE_NEW_USERS, 0) AS ONLINE_NU, COALESCE(ONLINE_REPEAT_USERS, 0) AS ONLINE_RU, COALESCE(OFFLINE_NEW_USERS, 0) AS OFFLINE_NU, COALESCE(OFFLINE_REPEAT_USERS, 0) AS OFFLINE_RU FROM master ), ctr AS ( SELECT TRIM(CAMPAIGN) AS CAPSULE, SUM(CLICKS) AS CLICKS, SUM(VIEWS) AS VIEWS, ROUND( SUM(CLICKS) * 100.0 / NULLIF(SUM(VIEWS), 0), 2 ) AS CTR FROM snitch_db.maplemonk.capsule_ctr_dashboard GROUP BY TRIM(CAMPAIGN) ), rolling_30 AS ( SELECT TRIM(CAPSULE) AS CAPSULE, SUM(LAST_30_QTY) AS LAST_30_UNITS, SUM(LAST_30_GROSS_SALES) AS LAST_30_GMV, SUM(LAST_30_DISCOUNT) AS LAST_30_DISCOUNT, ROUND( SUM(LAST_30_GROSS_SALES) / NULLIF(SUM(LAST_30_QTY), 0), 2 ) AS LAST_30_ASP, MAX(LAUNCH_DATE) AS LAUNCH_DATE, MAX(NORMALIZED_30_STR) AS NORMALIZED_30_STR, MAX(LAST_30_STR) AS LAST_30_STR FROM snitch_db.maplemonk.rolling_30_days_dashboard GROUP BY TRIM(CAPSULE) ), channel_sales AS ( SELECT TRIM(CAPSULE) AS CAPSULE, SUM( CASE WHEN CHANNEL_TYPE = \'Online\' THEN UNITS_SOLD ELSE 0 END ) AS ONLINE_UNITS, SUM( CASE WHEN CHANNEL_TYPE = \'Online\' THEN GROSS_SALES ELSE 0 END ) AS ONLINE_GMV, SUM( CASE WHEN CHANNEL_TYPE = \'Offline\' THEN UNITS_SOLD ELSE 0 END ) AS OFFLINE_UNITS, SUM( CASE WHEN CHANNEL_TYPE = \'Offline\' THEN GROSS_SALES ELSE 0 END ) AS OFFLINE_GMV FROM snitch_db.maplemonk.capsule_overview_dashboard WHERE CHANNEL_TYPE IN (\'Online\', \'Offline\') GROUP BY TRIM(CAPSULE) ), final_summary AS ( SELECT m.CAPSULE, r.LAUNCH_DATE, COALESCE(c.CLICKS, 0) AS CLICKS, COALESCE(c.VIEWS, 0) AS VIEWS, COALESCE(c.CTR, 0) AS CTR, COALESCE(cm.NEW_USERS, 0) AS NEW_USERS, COALESCE(cm.RETURNING_USERS, 0) AS RETURNING_USERS, COALESCE(cm.TOTAL_USERS, 0) AS TOTAL_USERS, COALESCE(cm.LOYAL_USERS, 0) AS LOYAL_USERS, COALESCE(cm.ONLINE_NU, 0) AS ONLINE_NU, COALESCE(cm.ONLINE_RU, 0) AS ONLINE_RU, COALESCE(cm.OFFLINE_NU, 0) AS OFFLINE_NU, COALESCE(cm.OFFLINE_RU, 0) AS OFFLINE_RU, ROUND( cm.NEW_USERS * 100.0 / NULLIF(cm.TOTAL_USERS, 0), 2 ) AS NU_PCT, ROUND( cm.RETURNING_USERS * 100.0 / NULLIF(cm.TOTAL_USERS, 0), 2 ) AS RU_PCT, m.UNITS_SOLD, m.GMV, m.ASP, m.TOTAL_DISCOUNT, m.DISCOUNT_PCT, m.UNITS_RECEIVED, m.CURRENT_INVENTORY, m.INVENTORY_VALUE, m.OPENING_GMV, m.SOLD_MERCHANDISE_VALUE, m.STR_LIFETIME, m.STR_REMAINING, m.INVENTORY_REMAINING_PCT, m.STOCK_COVER_DAYS, m.STR_STATUS, COALESCE(r.LAST_30_UNITS, 0) AS LAST_30_UNITS, COALESCE(r.LAST_30_GMV, 0) AS LAST_30_GMV, COALESCE(r.LAST_30_DISCOUNT, 0) AS LAST_30_DISCOUNT, COALESCE(r.LAST_30_ASP, 0) AS LAST_30_ASP, COALESCE(r.LAST_30_STR, 0) AS LAST_30_STR, COALESCE(r.NORMALIZED_30_STR, 0) AS NORMALIZED_30_STR, COALESCE(ch.ONLINE_UNITS, 0) AS ONLINE_UNITS, COALESCE(ch.ONLINE_GMV, 0) AS ONLINE_GMV, COALESCE(ch.OFFLINE_UNITS, 0) AS OFFLINE_UNITS, COALESCE(ch.OFFLINE_GMV, 0) AS OFFLINE_GMV, ROUND( COALESCE(ch.ONLINE_UNITS, 0) * 100.0 / NULLIF(m.UNITS_SOLD, 0), 2 ) AS ONLINE_UNIT_PCT, ROUND( COALESCE(ch.OFFLINE_UNITS, 0) * 100.0 / NULLIF(m.UNITS_SOLD, 0), 2 ) AS OFFLINE_UNIT_PCT, ROUND( COALESCE(ch.ONLINE_GMV, 0) * 100.0 / NULLIF(m.GMV, 0), 2 ) AS ONLINE_GMV_PCT, ROUND( COALESCE(ch.OFFLINE_GMV, 0) * 100.0 / NULLIF(m.GMV, 0), 2 ) AS OFFLINE_GMV_PCT, m.DAYS_ACTIVE, m.FIRST_INWARD_DATE, m.LATEST_INWARD_DATE, m.INWARD_EVENTS, m.REPEAT_ORDER, m.INVENTORY_AGE_BUCKET, CASE WHEN LOWER(TRIM(m.CAPSULE)) IN ( \'embroided shirts\', \'botanical theme\', \'street fc\', \'street fc plus\', \'golf polo theme\', \'photo print\', \'try less denim\', \'printed shirts\', \'luxe\' ) THEN \'YES\' ELSE \'NO\' END AS FOCUS_CAPSULE FROM master m LEFT JOIN customer_metrics cm ON LOWER(TRIM(m.CAPSULE)) = LOWER(TRIM(cm.CAPSULE)) LEFT JOIN ctr c ON LOWER(TRIM(m.CAPSULE)) = LOWER(TRIM(c.CAPSULE)) LEFT JOIN rolling_30 r ON LOWER(TRIM(m.CAPSULE)) = LOWER(TRIM(r.CAPSULE)) LEFT JOIN channel_sales ch ON LOWER(TRIM(m.CAPSULE)) = LOWER(TRIM(ch.CAPSULE)) ) SELECT * FROM final_summary ORDER BY GMV DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            